async function f(): Promise<number> {
  await new Promise<void>((r) => setTimeout(r, 2));
  return 3;
}
async function run(): Promise<void> {
  console.log("final", await f());
  console.log("k" + (await f()));
  const x = 10;
  console.log(x + (await f()), 1 + (await f()) * 2);
  const o = { a: 1, b: await f() };
  console.log(o);
  console.log([1, await f()]);
}
function main(): void {
  run();
}
